"""Writes the generated scenes from graphics/slots.json: one chips scene per chips slot and one launcher per chapter change."""
import json, re
slots = json.load(open('graphics/slots.json'))['slots']
launch = open('graphics/scenes/launch.html', encoding='utf-8').read()
ids = []
for s in slots:
    if s['kind'] == 'chips' and s.get('chips'):
        spec = {'dur': round(s['dur'], 4), 'chips': s['chips']}
        html = f'''<!doctype html><meta charset="utf-8">
<!-- generated by gen_auto.py from slots.json: do not edit -->
<link rel="stylesheet" href="../lib/stage.css"><script src="../lib/stage.js"></script>
<style>
  html,body{{background:transparent}}
  #row{{position:absolute;left:84px;bottom:92px;display:flex;gap:18px;align-items:center;max-width:1750px;flex-wrap:wrap}}
  .chip{{font-size:34px;padding:20px 34px 20px 24px}}
  #scrim{{position:absolute;left:0;right:0;bottom:0;height:300px;background:linear-gradient(180deg,transparent,rgba(0,0,0,.42))}}
</style>
<body class="alpha" data-nopush="1" data-clip="0,780,1920,300" data-dur="{spec['dur']}">
<div id="scrim"></div>
<div id="cam"><div id="row">{''.join(f'<div class="chip" data-in="{c["t"]}" data-fx="left" data-d="0.45"><i></i>{c["text"]}</div>' for c in spec['chips'])}</div></div>
<script>
const scrim = document.getElementById('scrim'), t0 = {min(c['t'] for c in spec['chips'])}, D = {spec['dur']};
Stage.on((t) => {{ const out = 1 - Stage.easeIO(Stage.p(t, D - 0.4, 0.4)); scrim.style.opacity = Stage.easeOut(Stage.p(t, t0, .4)) * out; document.getElementById('row').style.opacity = out; }});
</script>
</body>'''
        open(f"graphics/scenes/{s['id']}.html", 'w', encoding='utf-8').write(html); ids.append(s['id'])
    if s['kind'] == 'launch':
        h = launch.replace('data-dur="4"', f'data-dur="{s["dur"]:.4f}"').replace("parseInt(new URLSearchParams(location.search).get('a') || '1')", str(s['n']))
        h = h.replace('Stage.p(t, 0.0, 3.6)', f'Stage.p(t, 0.0, {s["dur"] - 0.3:.3f})')
        assert 'data-dur="4"' not in h and f"const N = {s['n']};" in h
        open(f"graphics/scenes/launch_{s['n']}.html", 'w', encoding='utf-8').write(h); ids.append(f"launch_{s['n']}")
open('work/auto_ids.txt', 'w').write(' '.join(ids)); print(len(ids), ' '.join(ids))
